 if(action==='onboard'&&mutationAllowed())onboardPanel();if(action==='onboard-review'){const tags=$('onboard-tags').value.split(/[,\s]+/).filter(Boolean);if(!tags.length||tags.some(x=>!/^tag:[a-zA-Z0-9-]+$/.test(x))||!$('onboard-file').value.trim()){$('onboard-error').textContent='请检查标签和保存文件路径。';return}const file=$('onboard-file').value.trim();onboardReady={file,tags};openPanel('确认接入配置',`${facts([['设备标签',tags.map(t=>esc(t)).join(', ')],['有效期',$('onboard-ttl').selectedOptions[0].text],['临时节点',$('onboard-ephemeral').checked?'是':'否'],['保存位置',esc(file)]])}${actions('创建预授权 Key','onboard-create')}`,'接入预览')}
 if(action==='onboard-create'&&onboardReady&&mutationAllowed()){const file=onboardReady.file;openPanel('设备接入配置已准备',`<div class="drawer-tip">演示：预授权 Key 将写入指定文件。</div><div class="resource-location">${esc(file)}</div><ol class="step-list"><li><span>将 key 文件交给新设备<small>仅向准备接入的设备提供</small></span></li><li><span>通过首次运行向导接入<small>选择 Tailnet 并指定 authkey_file</small></span></li><li><span>返回设备清单确认状态</span></li></ol><button class="button full" data-base-action="close">返回 Tailnet</button>`,'接入新设备')}
 if(action==='tag-preview'&&mutationAllowed()){const tags=[...new Set($('tag-input').value.split(/[,\s]+/).filter(Boolean))];if(tags.some(x=>!/^tag:[A-Za-z0-9-]+$/.test(x))){$('tag-error').textContent='标签格式应为 tag:名称。';return}const owners=JSON.parse(cloudPolicy).tagOwners||{};const missing=tags.filter(x=>!owners[x]);if(missing.length){$('tag-error').textContent='请先在已应用策略中配置标签属主：'+missing.join(', ');return}const device=devices.find(x=>x.id===d.id);tagPlan={id:d.id,tags};openPanel('预览标签变更',`<p class="drawer-description">${device.name}</p>${facts([['当前标签',esc(device.tags.join(', ')||'—')],['更新为',esc(tags.join(', ')||'空标签组')]])}${actions('确认写入标签','tag-apply')}`,'设备标签')}
 if(action==='tag-apply'&&tagPlan&&mutationAllowed()){const device=devices.find(x=>x.id===tagPlan.id);device.tags=tagPlan.tags;device.issue=device.tags.includes('tag:device')?undefined:'缺少设备标签';device.roles=device.tags.includes('tag:device')?'Agent':'Peer';closePanel();render();notify('演示：设备标签已更新')}
 if(action==='show-issues'){tab='devices';filter='issues';render()}if(action==='reset-search'){query='';filter='all';render()}
