 if(action==='relay-remove'&&mutationAllowed()){const obj=parsePolicy();delete obj.derpMap.Regions[d.id];updateDraft(obj);closePanel();render()}
 if(action==='probe-all'){for(const r of relayRegions())probeResults[r.RegionID]=r.RegionID===901?'42 ms':'68 ms';render();notify('全部中继的示例探测已完成')}
 if(action==='admission'&&mutationAllowed())openPanel('中继准入同步',`<p class="drawer-description">把已授权设备同步到自建 DERP 的准入服务。</p>${selectField('同步方式','admission-mode',[['file','写入本机放行文件'],['remote','推送到远端服务']],'file')}<div id="admission-fields">${field('放行文件','admission-target','/tmp/xmesh-derp-allowlist.json')}</div><p id="admission-error" class="form-error"></p>${actions('预览同步','admission-review')}`,'DERP 管理');
 if(action==='admission-review'){if(!$('admission-target').value.trim()){$('admission-error').textContent='请填写目标。';return}openPanel('预览准入同步',`${facts([['已授权设备',devices.filter(x=>x.authorized).length+' 台'],['目标',esc($('admission-target').value)]])}<p class="small-hint" style="margin-top:16px">已建立的中继连接在重新连接后使用更新的准入规则。</p>${actions('确认同步','admission-apply')}`,'准入同步')}
 if(action==='admission-apply'&&mutationAllowed()){closePanel();notify('演示：准入规则同步完成')}
